// REAL and testable: shared-secret check (this is an EXTERNAL vendor-facing endpoint, a
// different trust boundary from the internal event->n8n bridge, hence its own secret rather than
// reusing N8N_BRIDGE_SECRET) + at-least-once dedupe on taskId (design §11: 'inbound webhooks are
// notification-only... authoritative data always re-fetched'; the payload is never trusted as
// data past the taskId/correlation fields -- everything else is re-derived platform-side).
const got = $input.first().json.headers?.['x-gaiada-search-callback-secret'];
if (!got || got !== $env.SEARCH_CALLBACK_SECRET) throw new Error('bad callback secret');
const body = $input.first().json.body ?? {};
const { engagementId, propertyId, keywordId, taskId } = body;
// See workflow meta.description point (2): a genuine DataForSEO postback would NOT carry
// engagementId/propertyId/keywordId -- this validates the shape the REAL platform route
// requires today, which is a documented gap, not an assumption this code silently papers over.
if (!engagementId || !propertyId || !keywordId) {
  throw new Error('payload missing engagementId/propertyId/keywordId -- see workflow meta.description: unsolved task-id correlation gap');
}
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const dedupeKey = taskId || `${engagementId}:${propertyId}:${keywordId}`;
const dup = Object.prototype.hasOwnProperty.call(store.seen, dedupeKey);
if (!dup) {
  store.seen[dedupeKey] = Date.now();
  const keys = Object.keys(store.seen);
  if (keys.length > 1000) for (const k of keys.slice(0, keys.length - 1000)) delete store.seen[k];
}
return [{ json: { dup, engagementId, propertyId, keywordId, taskId: taskId ?? null } }];
